from dataclasses import dataclass

@dataclass
class Entry:
    value: object
    timestamp: int
    node_id: str

class LwwCache:
    def __init__(self, node_id, bus, clock):
        self.node_id = node_id
        self.bus = bus
        self.clock = clock
        self.data = {}

    def read(self, key):
        return self.data.get(key)

    def write(self, key, value):
        entry = Entry(value, self.clock.now(), self.node_id)
        self.data[key] = entry
        self.bus.publish(key, entry)
        return entry

    def apply_remote(self, key, incoming):
        current = self.data.get(key)
        if current is None or (incoming.timestamp, incoming.node_id) > (current.timestamp, current.node_id):
            self.data[key] = incoming

    def repair(self, key, replicas):
        candidates = [r.read(key) for r in replicas]
        candidates = [e for e in candidates if e is not None]
        if candidates:
            winner = max(candidates, key=lambda e: (e.timestamp, e.node_id))
            self.data[key] = winner
            return winner
        return None
